use soroban_sdk::{contract, contractimpl, Env};

#[contract]
pub struct Batch;

#[contractimpl]
impl Batch {
    // 15 x 20 = 300 ledger entries read, over the 200 an invocation is allowed.
    // Every loop bound is a literal, so this call fails for every caller.
    pub fn sweep(env: Env) {
        for i in 0..15 {
            for j in 0..20 {
                env.storage().persistent().get(&(i, j));
            }
        }
    }
}

