use soroban_sdk::{contract, contractimpl, Env};

#[contract]
pub struct Batch;

#[contractimpl]
impl Batch {
    // 10 x 10 = 100 entries, comfortably inside the ceiling.
    pub fn sweep(env: Env) {
        for i in 0..10 {
            for j in 0..10 {
                env.storage().persistent().get(&(i, j));
            }
        }
    }
}
